// Generate TypeScript from the JSON Schemas exported by the Python service.
// For each schemas/<name>.json this writes src/generated/<name>.ts containing:
//   - the TypeScript types (via json-schema-to-typescript)
//   - the schema itself as a const, for runtime validation with Ajv
// Do not edit generated files by hand; change the Pydantic model and rerun `pnpm contracts:gen`.
import { readdir, readFile, writeFile, mkdir } from 'node:fs/promises';
import { join, dirname, basename } from 'node:path';
import { fileURLToPath } from 'node:url';
import { compile } from 'json-schema-to-typescript';

const root = dirname(dirname(fileURLToPath(import.meta.url)));
const schemaDir = join(root, 'schemas');
const outDir = join(root, 'src', 'generated');

const toPascal = (s) =>
  s
    .replace(/\.v\d+$/, '')
    .split(/[-_.]/)
    .map((p) => p[0].toUpperCase() + p.slice(1))
    .join('');

// Pydantic titles every field ("Status", "Latency Ms"), which makes json-schema-to-typescript
// emit one alias type per field (Status, Status1, ...). Keep titles only on models.
const withoutFieldTitles = (node) => {
  if (Array.isArray(node)) return node.map(withoutFieldTitles);
  if (node === null || typeof node !== 'object') return node;
  const out = {};
  for (const [key, value] of Object.entries(node)) {
    if (key === 'properties') {
      out.properties = Object.fromEntries(
        Object.entries(value).map(([prop, sub]) => {
          const rest = { ...sub };
          delete rest.title;
          return [prop, withoutFieldTitles(rest)];
        }),
      );
    } else {
      out[key] = withoutFieldTitles(value);
    }
  }
  return out;
};

await mkdir(outDir, { recursive: true });
const files = (await readdir(schemaDir)).filter((f) => f.endsWith('.json')).sort();

for (const file of files) {
  const name = basename(file, '.json');
  const schema = JSON.parse(await readFile(join(schemaDir, file), 'utf8'));
  const types = await compile(withoutFieldTitles(schema), schema.title ?? toPascal(name), {
    bannerComment: '',
    additionalProperties: false,
    format: false,
    strictIndexSignatures: true,
  });
  const constName = `${toPascal(name)}Schema`;
  const body = [
    `// GENERATED by packages/contracts/scripts/generate.mjs from schemas/${file}. Do not edit.`,
    '/* eslint-disable */',
    '',
    types.trim(),
    '',
    `export const ${constName} = ${JSON.stringify(schema, null, 2)} as const;`,
    '',
  ].join('\n');
  await writeFile(join(outDir, `${name}.ts`), body);
  console.log(`wrote src/generated/${name}.ts`);
}
